INSERT INTO facts (area, title, short_fact, long_fact, category) VALUES
  ('Bolivar', 'Named for Simón Bolívar', 'The peninsula is named for Simón Bolívar, the South American liberator.', 'Bolivar Peninsula takes its name from Simón Bolívar, the leader of independence movements in South America.', 'history'),
  ('Bolivar', 'Narrow barrier landform', 'Bolivar Peninsula is a narrow strip of eroding land along the Texas Gulf Coast.', 'Bolivar Peninsula is a narrow, eroding barrier landform stretching along the Texas Gulf Coast.', 'geography'),
  ('Bolivar', 'About 27 miles long', 'The peninsula stretches twenty-seven miles along the Texas Gulf Coast.', 'Bolivar Peninsula extends about 27 miles along the Texas Gulf Coast.', 'geography'),
  ('Bolivar', 'Forms eastern Galveston County', 'It forms the eastern part of Galveston County.', 'Bolivar Peninsula makes up the eastern part of Galveston County.', 'geography'),
  ('Bolivar', 'Separates bay from gulf', 'It separates the eastern part of Galveston Bay from the Gulf of Mexico.', 'Bolivar Peninsula lies between Galveston Bay and the Gulf of Mexico.', 'geography'),
  ('Bolivar', 'Short ferry ride from Galveston', 'The peninsula is a short ferry ride from Galveston, Texas.', 'Travel between Galveston and Bolivar is commonly done by ferry.', 'transportation'),
  ('Bolivar', 'Ferry is toll-free', 'The Galveston-Port Bolivar Ferry is a toll-free service operated by TxDOT.', 'Riding the Galveston-Port Bolivar Ferry does not require a toll.', 'transportation'),
  ('Bolivar', 'Ferry runs 24 hours', 'The ferry operates 24 hours a day.', 'Ferry service between Galveston and Bolivar runs around the clock.', 'transportation'),
  ('Bolivar', 'Ferry began in 1930', 'Ferry service began on April 12, 1930.', 'The Galveston-Port Bolivar Ferry started operating on April 12, 1930.', 'history'),
  ('Bolivar', 'Port Bolivar ferry terminal', 'The Port Bolivar ferry terminal is at 123 SH 87, Port Bolivar, TX.', 'Port Bolivar is one of the ferry endpoints on SH 87.', 'transportation'),
  ('Bolivar', 'Galveston terminal on Ferry Road', 'The Galveston terminal is at 1000 Ferry Road, Galveston, TX.', 'Galveston''s ferry terminal sits on Ferry Road.', 'transportation'),
  ('Bolivar', 'Ferry may stop in severe weather', 'Service may be reduced or stopped during severe weather for safety.', 'The ferry can be limited or suspended when weather is dangerous.', 'transportation'),
  ('Bolivar', 'Includes Port Bolivar community', 'The peninsula includes the community of Port Bolivar.', 'Port Bolivar is one of the named communities on Bolivar Peninsula.', 'communities'),
  ('Bolivar', 'Includes Crystal Beach', 'The peninsula includes Crystal Beach.', 'Crystal Beach is a major community on Bolivar Peninsula.', 'communities'),
  ('Bolivar', 'Includes Caplen', 'The peninsula includes Caplen.', 'Caplen is part of the Bolivar Peninsula community cluster.', 'communities'),
