  ('Bolivar', 'Includes High Island', 'The peninsula includes High Island.', 'High Island is part of the broader Bolivar Peninsula area.', 'communities'),
  ('Bolivar', 'Popular for fishing', 'It is popular for fishing.', 'Fishing is one of the common recreation activities on Bolivar Peninsula.', 'recreation'),
  ('Bolivar', 'Popular for boating', 'It is popular for boating.', 'Boating is a common use of the waters around Bolivar Peninsula.', 'recreation'),
  ('Bolivar', 'Popular for bird watching', 'It is popular for bird watching.', 'Bird watching is a well-known activity on Bolivar Peninsula.', 'recreation'),
  ('Bolivar', 'Popular for beach days', 'It is popular for spending a day on the beach.', 'Visitors often go to Bolivar Peninsula for beach time.', 'recreation'),
  ('Bolivar', 'Bolivar Beach Pavilion', 'Bolivar Beach Pavilion offers beach access, parking, restrooms, and rinse-off showers.', 'Bolivar Beach Pavilion is a public beach facility with visitor amenities.', 'amenities'),
  ('Bolivar', 'Fort Travis in Port Bolivar', 'Fort Travis Park is at 800 Anderson Ave., Port Bolivar.', 'Fort Travis Park is located in Port Bolivar on Bolivar Peninsula.', 'history'),
  ('Bolivar', 'Fort Travis is historic', 'Fort Travis Park is listed as a historic site.', 'Fort Travis Park is recognized as a historic location.', 'history'),
  ('Bolivar', 'Point Bolivar Lighthouse guided ships', 'The Point Bolivar Lighthouse guided boat traffic through Bolivar Roads.', 'The lighthouse helped guide vessels through the pass between bay and gulf.', 'history'),
  ('Bolivar', 'Lighthouse operated 1873 to 1933', 'It operated from 1873 to 1933.', 'The Point Bolivar Lighthouse was in service for six decades.', 'history'),
  ('Bolivar', 'Bolivar Roads is a narrow pass', 'Bolivar Roads is a 1.5-mile-wide pass between the Gulf and the Bay.', 'Bolivar Roads is the narrow maritime passage near Bolivar Peninsula.', 'geography'),
  ('Bolivar', 'High Island on a salt dome', 'High Island sits atop a salt dome about 45 feet above sea level.', 'High Island rises unusually high because it rests on a salt dome.', 'geology'),
  ('Bolivar', 'High Island stays dry in floods', 'During severe flooding it is the only dry land seen for miles.', 'High Island becomes a rare dry spot during big coastal floods.', 'geology'),
  ('Bolivar', 'High Island settled in 1834', 'Martin Dunman settled at High Island in 1834.', 'High Island''s recorded settlement dates to 1834.', 'history'),
  ('Bolivar', 'Rail access by 1886', 'The Gulf and Interstate Railroad built a railroad to Beaumont along Bolivar Peninsula in 1886.', 'Rail development reached High Island and the peninsula in the late 1800s.', 'history'),
  ('Bolivar', 'High Island had mineral springs', 'For a time the community was known for its mineral springs.', 'High Island once had a reputation for mineral springs.', 'history'),
  ('Bolivar', 'High Island oil boom', 'Oil was discovered in 1916 and a major oil boom followed in the 1930s and 1940s.', 'High Island became part of a regional oil boom after discovery in 1916.', 'history'),
  ('Bolivar', 'Seaview Hotel sheltered residents', 'The Seaview Hotel served as shelter during hurricanes in 1900 and 1915.', 'A hotel in the area provided refuge during major hurricanes.', 'history'),
