  ('Bolivar', 'About 2 cars per household', 'Average car ownership was 2 cars per household.', 'Households on Bolivar Peninsula typically have about two cars.', 'transportation'),
  ('Bolivar', 'Mostly English-speaking', 'None of the households reported a non-English language as the primary shared language at home.', 'English is the dominant home language on Bolivar Peninsula.', 'demographics'),
  ('Bolivar', 'Majority White non-Hispanic', 'White non-Hispanic residents were the largest ethnic group.', 'Bolivar Peninsula''s population is majority White non-Hispanic.', 'demographics'),
  ('Bolivar', '93.5 percent U.S. citizens', '93.5 percent of residents were U.S. citizens.', 'Most Bolivar Peninsula residents are U.S. citizens.', 'demographics'),
  ('Bolivar', 'Long-time vacation-home area', 'The peninsula had hundreds of vacation-home owners and weekend visitors in the 1990s.', 'Bolivar Peninsula has long been a second-home and weekend destination.', 'tourism'),
  ('Bolivar', 'Eroding barrier landform', 'It is described as an eroding landform.', 'Coastal erosion is part of Bolivar Peninsula''s physical reality.', 'geography'),
  ('Bolivar', 'Southeast Texas coast', 'It stretches along the Texas Gulf Coast in eastern Galveston County.', 'Bolivar Peninsula sits on the southeast Texas shoreline.', 'geography'),
  ('Bolivar', 'Center at 29°26 N, 94°41 W', 'The center of the peninsula is at 29°26 N, 94°41 W.', 'The peninsula''s center has published geographic coordinates.', 'geography'),
  ('Bolivar', 'Beach access at the Pavilion', 'Bolivar Beach Pavilion offers beach access and parking.', 'Public access infrastructure supports beach visits on Bolivar Peninsula.', 'amenities'),
  ('Bolivar', 'National Register historic sites', 'Fort Travis and Point Bolivar Lighthouse are listed on the National Register of Historic Places in Texas.', 'Bolivar Peninsula contains nationally recognized historic places.', 'history'),
  ('Bolivar', 'Strong recreation identity', 'Outdoor recreation is a major theme for the peninsula.', 'Bolivar is known for outdoor leisure rather than dense urban development.', 'recreation'),
  ('Bolivar', 'Ferry is the main access point', 'The ferry is the main connection between Galveston Island and the peninsula.', 'Access to Bolivar often depends on the ferry crossing.', 'transportation'),
  ('Bolivar', 'Part of county parks system', 'The county parks page identifies the peninsula as a park/recreation area.', 'County government treats Bolivar Peninsula as a recreation destination.', 'government'),
  ('Bolivar', 'Crystal Beach has a pavilion', 'Crystal Beach is within Bolivar and has a dedicated beach pavilion.', 'Crystal Beach is a central beach community on Bolivar Peninsula.', 'communities'),
